import sys
from collections import deque

def quickestWayUp(ladders, snakes):
    board = [-1] * 101
    for start, end in ladders:
        board[start] = end
    for start, end in snakes:
        board[start] = end

    def bfs():
        queue = deque([(1, 0)])
        visited = [False] * 101
        visited[1] = True

        while queue:
            current, rolls = queue.popleft()
            if current == 100:
                return rolls

            for dice in range(1, 7):
                next_pos = current + dice
                if next_pos > 100:
                    continue
                if board[next_pos] != -1:
                    next_pos = board[next_pos]
                if not visited[next_pos]:
                    visited[next_pos] = True
                    queue.append((next_pos, rolls + 1))

        return -1

    return bfs()

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    t = int(data[index])
    index += 1
    results = []

    for _ in range(t):
        n = int(data[index])
        index += 1
        ladders = []
        for _ in range(n):
            start = int(data[index])
            end = int(data[index + 1])
            ladders.append((start, end))
            index += 2

        m = int(data[index])
        index += 1
        snakes = []
        for _ in range(m):
            start = int(data[index])
            end = int(data[index +1])
            snakes.append((start, end))
            index += 2

        result = quickestWayUp(ladders, snakes)
        results.append(result)

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
